import { NotFoundError } from "../domain/errors";
import { IdGenerator } from "../domain/id-generator";
import { ProjectRepository } from "../domain/project-repository";
import { Task } from "../domain/task";
import { TaskRepository } from "../domain/task-repository";
import { AddTaskInput, TaskDto, toTaskDto } from "./dtos";

export class AddTaskUseCase {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly tasks: TaskRepository,
    private readonly ids: IdGenerator,
  ) {}

  async execute(input: AddTaskInput): Promise<TaskDto> {
    if (!(await this.projects.findById(input.projectId))) {
      throw new NotFoundError(`project ${input.projectId} not found`);
    }
    const task = Task.create({
      id: this.ids.next(),
      projectId: input.projectId,
      title: input.title,
      description: input.description,
      dueDate: input.dueDate === undefined ? undefined : new Date(input.dueDate),
      status: input.status,
    });
    await this.tasks.save(task);
    return toTaskDto(task);
  }
}

=====SOURCE-END=====

