export interface TaskDto {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate: string | null;
  status: TaskStatus;
  assigneeId: string | null;
}

export const toUserDto = (user: User): UserDto => ({ id: user.id, name: user.name });

export const toProjectDto = (project: Project): ProjectDto => ({
  id: project.id,
  name: project.name,
});

export const toTaskDto = (task: Task): TaskDto => ({
  id: task.id,
  projectId: task.projectId,
  title: task.title,
  description: task.description,
  dueDate: task.dueDate ? task.dueDate.toISOString() : null,
  status: task.status,
  assigneeId: task.assigneeId ?? null,
});

